use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,io::{BufRead,BufReader},path::{Path,PathBuf},process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/serial-phi175";fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap();}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn prepare(){assert_eq!(read(r("runs/completed.json")).as_array().unwrap().len(),498);assert_eq!(read(r("runs/decode-cycles-1x2-w32-accept/exit.json"))["returncode"],255);assert!(!r("decode-plan.json").exists());let mut s=fs::read_to_string(r("capture.rs")).unwrap();s=s.replace("read(r(\"runs/result.json\"))","read(r(\"decoded/result.json\"))");for stage in["decode","evlist","loss"]{s=s.replace(&format!("runs/{stage}-{{name}}/stdout.log"),&format!("decoded/{stage}-{{name}}/stdout.log"));}let at=s.rfind("fn main() {").unwrap();s.truncate(at);s.push_str("fn main(){assert_eq!(read(r(\"runs/completed.json\")).as_array().unwrap().len(),498);for(p,h)in read(r(\"postcapture-pins.json\")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}finish();}\n");fs::write(r("finish.rs"),s).unwrap();
let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}let mut steps=vec![];for j in read(r("jobs.json")).as_array().unwrap().iter().filter(|j|j["diagnostic"]==true){let name=j["name"].as_str().unwrap();let data=j["data"].as_str().unwrap();pins.insert(data.into(),hash(data));steps.push(json!({"kind":"command","name":format!("decode-{name}"),"argv":["perf","script","--header","--show-lost-events","-i",data,"-F","pid,tid,period,ip,sym"],"timeout_seconds":180}));steps.push(json!({"kind":"command","name":format!("evlist-{name}"),"argv":["perf","evlist","-v","-i",data],"timeout_seconds":120}));steps.push(json!({"kind":"command","name":format!("loss-{name}"),"argv":[r("decode-helper"),"loss",data],"timeout_seconds":180}));}assert_eq!(steps.len(),18);for f in["decode.rs","decode-helper","finish.rs","runs/failure.json","runs/completed.json","runs/decode-cycles-1x2-w32-accept/exit.json","runs/decode-cycles-1x2-w32-accept/stderr.log"]{pins.insert(r(f).display().to_string(),hash(r(f)));}save(r("postcapture-pins.json"),&json!(pins));save(r("decode-plan.json"),&json!({"version":1,"source_pins":r("postcapture-pins.json"),"steps":steps}));save(r("postcapture-repair.json"),&json!({"stage":"offline decode, after every capture and independent proof verification","original_successful_steps":498,"failed_decode_exit":255,"cause":"sudo perf rejected already chowned data: current user root differs from owner ubuntu","repair":"same offline decoding as owner ubuntu, separate18stepworkflow; existing data unchanged","captures_repeated":0,"proof_verifications_repeated":0,"native_builds_tests_repeated":0,"original_protocol_and_failure_retained":true,"analysis_paths_only_changed":"read decoded/result.json and decoder stdout from decoded; latency/verification inputs/gates unchanged"}));println!("Prepared18offline owner-decode steps; every246proof alreadyverified; no capture restart");}
fn loss(data:&str){let mut child=Command::new("perf").args(["script","-D","-i",data]).stdout(Stdio::piped()).spawn().unwrap();let mut n=0;let mut lost=vec![];for l in BufReader::new(child.stdout.take().unwrap()).lines(){let l=l.unwrap();n+=1;if l.contains("PERF_RECORD_LOST"){lost.push(l);}}assert!(child.wait().unwrap().success());println!("{}",json!({"raw_decoded_lines":n,"lost_records":lost,"zero_lost":lost.is_empty()}));}
fn main(){match std::env::args().nth(1).as_deref(){Some("prepare")=>prepare(),Some("loss")=>loss(&std::env::args().nth(2).unwrap()),_=>panic!("prepare|loss")}}
